from pathlib import Path; import subprocess; p=Path('AGENTS.md'); t=p.read_text(encoding='utf-8'); h='## Browser bridge visible-chat transport'; s=chr(10)*2+h+chr(10)*2+'Harde operationele regel: een bridge-taak moet daadwerkelijk als gewone zichtbare assistant-chattekst in de ChatGPT-interface staan. Een taak die alleen via commentary, tool-output of een andere verborgen laag wordt uitgegeven geldt als NIET VERZONDEN.'+chr(10)+'Als de gebruiker de taak niet ziet, stuur hem opnieuw zichtbaar en wacht niet op de onzichtbare poging.'+chr(10)+'Bridge-payloads moeten parser-safe blijven: vermijd multiline stringconstructies en documenteer transportmarkeringen niet letterlijk binnen payloadvelden.'+chr(10); changed=h not in t; p.write_text(t.rstrip()+s+chr(10),encoding='utf-8') if changed else None; subprocess.run(['git','add','AGENTS.md'],check=True) if changed else None; subprocess.run(['git','commit','-m','docs: persist bridge visibility lesson','--','AGENTS.md'],check=True) if changed else None; print('RULE_PRESENT='+str(h in p.read_text(encoding='utf-8'))); print('CHANGED='+str(changed)); print('HEAD='+subprocess.run(['git','rev-parse','HEAD'],text=True,capture_output=True,check=True).stdout.strip())